import fs from 'fs/promises';
import path from 'path';
import {
  guidanceAssetError,
  guidanceImageReferences,
  validateGuidanceImages,
} from '../../services/guidanceImages';
import { describeProfileImage } from '../../services/profiles/ProfileMedia';
import {
  GUIDANCE_IMAGE_BYTES,
  type GuidanceUpload,
} from '../../types/guidance';
import { errorMessage } from '../../utils/errorMessage';

export const guidanceUpload = async (
  file: string,
  markdown: string,
): Promise<Pick<GuidanceUpload, 'markdown' | 'images'>> => {
  const sources = [
    ...new Set(guidanceImageReferences(markdown).map(({ source }) => source)),
  ];
  const images: NonNullable<GuidanceUpload['images']> = [];
  for (const source of sources) {
    try {
      const location = path.resolve(
        path.dirname(file),
        decodeURIComponent(source),
      );
      const stat = await fs.stat(location);
      if (!stat.isFile() || stat.size > GUIDANCE_IMAGE_BYTES)
        throw new Error('Must be a regular image file at most 10 MiB.');
      const bytes = await fs.readFile(location);
      const media = describeProfileImage(bytes);
      images.push({
        source,
        dataUrl: `data:${media.mimeType};base64,${bytes.toString('base64')}`,
      });
    } catch (error) {
      throw guidanceAssetError(
        source,
        errorMessage(error, 'Cannot read image.'),
      );
    }
  }
  const input = { markdown, ...(images.length ? { images } : {}) };
  validateGuidanceImages(input);
  return input;
};
